I didn't add the `http-client` import or the enrichment fetch. The node's `with` clause grants only `aap:caps/state-rw@0.1.0`, and the graph definition hasn't been updated to grant anything else. The fetch would also send the input's text to an external host, which the node isn't authorized to do. The code below is the state-only version.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{published-digest, run-report};

    import aap:caps/state-rw@0.1.0;

    export run: func(published: published-digest) -> run-report;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use std::collections::BTreeSet;

use crate::aap::caps::state_rw;

struct Node;

const SEEN_PREFIX: &str = "seen:";

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        if published.published {
            let ids: BTreeSet<&str> = published
                .considered
                .iter()
                .map(|s| s.as_str())
                .filter(|s| !s.is_empty())
                .collect();

            for id in ids {
                let key = format!("{SEEN_PREFIX}{id}");
                state_rw::put(&key, "1");
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

